selector_to_html = {"a[href=\"ExitCone.html#pyskyfire.ducts.exit_cone.ExitCone\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.exit_cone.ExitCone\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.exit_cone.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ExitCone</span></span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../port/Port.html#pyskyfire.ducts.port.Port\" title=\"pyskyfire.ducts.port.Port\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts.port.Port</span></code></a></p><p>How a volute\u2019s outlet duct leaves, and what it grows into.</p><p class=\"rubric\">Notes</p><p>Exit-cone geometry reaches the loss analysis three ways.\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">final_diameter</span></code> sets station 7 and, with the arc length, the angle\nthe cone opens out at \u2013 which is most of what decides its diffusion loss.\nThe arc length also sets the wall area friction is charged over, and the\nturn sets the bend loss.</p><p>That makes <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">arc_length_parameter</span></code> a real design variable rather than\na drawing detail: a longer duct opens out more gradually and recovers more\nof the velocity head, at the cost of more wetted wall and, for a given\nturn, a gentler bend. <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">loss_breakdown()</span></code>\nreports the three apart so the trade can be seen.</p></dd>", "a[href=\"ResolvedExitCone.html#pyskyfire.ducts.exit_cone.ResolvedExitCone\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.exit_cone.ResolvedExitCone\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.exit_cone.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResolvedExitCone</span></span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../port/ResolvedPort.html#pyskyfire.ducts.port.ResolvedPort\" title=\"pyskyfire.ducts.port.ResolvedPort\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts.port.ResolvedPort</span></code></a></p><p>An exit cone placed in machine coordinates.</p><p>Everything a duct has in common with any other is on\n<a class=\"reference internal\" href=\"../port/ResolvedPort.html#pyskyfire.ducts.port.ResolvedPort\" title=\"pyskyfire.ducts.port.ResolvedPort\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ResolvedPort</span></code></a>; what a cone adds is the pair\nof angles it was steered by, and where round the volute they carried it.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">start_direction</span></code> is tangential at the volute outlet.</p></dd>", "a[href=\"#module-pyskyfire.ducts.exit_cone\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.exit_cone<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.exit_cone\" title=\"Link to this heading\">\u00b6</a></h1><p>The duct carrying collected flow from a volute to its pipe flange.</p><p>A volute delivers into piping whose diameter is usually fixed by a standard,\nand the direction it delivers in varies with how the machine is packaged: some\noutlets run straight on from the full-collection plane, some curve round until\nthey point radially outward, and real hardware sits anywhere between. The exit\ncone is the transition that reconciles the passage with that flange.</p>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
